import dev.hua.ptcglive.ai.*;
import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

public final class NonPokemonBatch109Test {
    static final UUID A=DynamicPassiveModifierTest.A,B=DynamicPassiveModifierTest.B;
    static final List<String> TOOLS=List.of("sm11_en_211"),ENERGIES=List.of("sm11_en_212","sm11_en_257");
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static UUID other(UUID p){return p.equals(A)?B:A;}
    static UUID active(ServerMatch m,UUID p){return m.activePokemonView(p).pokemonId();}
    static UUID bench(ServerMatch m,UUID p){return m.benchPokemonView(p).getFirst().pokemonId();}
    static CardInstance hand(ServerMatch m,UUID p,String id){return DynamicPassiveModifierTest.hand(m,p,id);}
    static TrainerProfile tool(){return NonPokemonBatch2Test.DATA.trainer(TOOLS.getFirst()).orElseThrow();}
    static EnergyProfile recycle(){return NonPokemonBatch2Test.DATA.energyProfile(ENERGIES.getFirst()).orElseThrow();}
    static TrainerProfile trainer(String id){return NonPokemonBatch2Test.DATA.trainer(id).orElseThrow();}
    static void settle(ServerMatch m){NonPokemonBatch103Test.settle(m);}
    static ServerMatch game(TrainerProfile stadium,TrainerProfile item,AttackDefinition attack){return DynamicPassiveModifierTest.fixture(tool(),stadium,recycle(),attack,List.of(),0,item);}
    static ServerMatch game(){return game(DynamicPassiveModifierTest.plainStadium(),trainer("sm2_en_125"),GeneratedRuleBatch8Test.hit(100,false));}
    static ServerMatch aiGame(String id){return NonPokemonBatch78Test.fixture(tool(),NonPokemonBatch2Test.DATA.energyProfile(ENERGIES.contains(id)?id:ENERGIES.getFirst()).orElseThrow(),GeneratedRuleBatch8Test.hit(300,false),true,null,false);}
    static CardInstance attach(ServerMatch m,UUID owner,UUID hostOwner,UUID host,String id){var c=hand(m,owner,id);if(id.equals("tool"))m.attachToolByEffect(m.currentPlayer(),owner,EffectSourceZone.HAND,c.instanceId(),hostOwner,host);else m.attachEnergyByEffect(m.currentPlayer(),owner,EffectSourceZone.HAND,c.instanceId(),hostOwner,host);return c;}
    static void returned(ServerMatch m,CardInstance c,boolean expected){check(m.privateView(c.ownerId()).hand().contains(c)==expected,"Wrong return owner/destination: "+c.definitionId());check(m.privateView(c.ownerId()).discard().contains(c)!=expected,"Duplicate/missing returned card: "+c.definitionId());}
    public static void main(String[] args){disposal();offField();suppression();simultaneous();lostZone();retreat();attackPayment();knockoutOrder();failedAttachment();ai();schema();System.out.println("NonPokemonBatch109Test passed: U-Turn Board/Recycle Energy mandatory enabled field-discard replacement, both controllers/positions, field effects/KO/retreat/attack payments, reused physical cards and hand/deck exclusions, Labs/Temple/Tool suppression including simultaneous Field Blower, direct Lost Zone exclusion, Lucky Egg before return, failed hand attachment and four AI difficulties");}
    static void disposal(){for(UUID owner:List.of(A,B))for(boolean onBench:List.of(false,true))for(String cause:List.of("discard","knockout","leave")){
        var m=game();if(owner.equals(B))m.endTurn(A);UUID host=onBench?bench(m,owner):active(m,owner),physical=owner;var board=attach(m,physical,owner,host,"tool");var energy=attach(m,physical,owner,host,"special");var basic=attach(m,owner,owner,host,"energy");
        if(cause.equals("discard")){m.discardToolByEffect(owner,owner,host,board.instanceId());m.discardAttachedEnergyByEffect(owner,owner,host,List.of(energy.instanceId(),basic.instanceId()));}else if(cause.equals("knockout"))m.knockOutPokemonByEffect(owner,owner,host);else m.movePokemonByEffect(owner,owner,host,LeavePlayDestination.DISCARD);settle(m);returned(m,board,true);returned(m,energy,true);check(m.privateView(owner).discard().contains(basic),"Ordinary Energy returned");
    }}
    static void offField(){for(String kind:List.of("tool","special"))for(boolean deck:List.of(false,true)){var m=game();var card=hand(m,A,kind);if(deck){PairedTrainerPlayTest.zone(m,A,"hand").remove(card);PairedTrainerPlayTest.zone(m,A,"deck").add(card);m.discardTopDeckCardsByEffect(A,A,1);}else m.discardHandCardsByEffect(A,A,List.of(card.instanceId()));returned(m,card,false);}
        var m=game();UUID host=active(m,A);var card=attach(m,A,A,host,"special");m.discardAttachedEnergyByEffect(A,A,host,List.of(card.instanceId()));returned(m,card,true);m.attachEnergyByEffect(A,A,EffectSourceZone.HAND,card.instanceId(),A,host);m.discardAttachedEnergyByEffect(A,A,host,List.of(card.instanceId()));returned(m,card,true);m.discardHandCardsByEffect(A,A,List.of(card.instanceId()));returned(m,card,false);
        var n=game();var board=attach(n,A,A,bench(n,A),"tool");var en=attach(n,A,A,bench(n,A),"special");n.movePokemonByEffect(A,A,bench(n,A),LeavePlayDestination.DECK_SHUFFLED);check(n.privateView(A).deck().containsAll(List.of(board,en))&&!n.privateView(A).hand().contains(board)&&!n.privateView(A).hand().contains(en),"Deck destination incorrectly replaced");
    }
    static void suppression(){for(boolean energy:List.of(false,true))for(boolean removeFirst:List.of(false,true)){
        var m=game(trainer(energy?"swsh10_en_155":"sm6_en_111"),trainer("sm2_en_125"),GeneratedRuleBatch8Test.hit(100,false));var c=attach(m,A,A,active(m,A),energy?"special":"tool");m.playTrainer(A,hand(m,A,"stadium").instanceId(),null);if(removeFirst)m.discardStadiumByEffect(A);if(energy)m.discardAttachedEnergyByEffect(A,A,active(m,A),List.of(c.instanceId()));else m.discardToolByEffect(A,A,active(m,A),c.instanceId());returned(m,c,removeFirst);
    }var m=game();var c=attach(m,A,A,active(m,A),"tool");m.disableToolEffectsByEffect(A,A,active(m,A));m.discardToolByEffect(A,A,active(m,A),c.instanceId());returned(m,c,false);}
    static void simultaneous(){for(boolean reverse:List.of(false,true)){
        var m=game(trainer("sm6_en_111"),trainer("sm2_en_125"),GeneratedRuleBatch8Test.hit(100,false));var card=attach(m,A,A,active(m,A),"tool");var stadium=hand(m,A,"stadium");m.playTrainer(A,stadium.instanceId(),null);m.playTrainer(A,hand(m,A,"item").instanceId(),null);var q=m.effectCardPrompt(A);m.submitEffectCards(A,q.resolutionId(),q.step(),reverse?List.of(stadium.instanceId(),card.instanceId()):List.of(card.instanceId(),stadium.instanceId()));settle(m);returned(m,card,false);check(m.clientView(A).stadium()==null,"Blower failed simultaneous Stadium discard");
    }}
    static void lostZone(){for(String kind:List.of("tool","special")){
        var m=game(DynamicPassiveModifierTest.plainStadium(),trainer("sm8_en_173"),GeneratedRuleBatch8Test.hit(100,false));var card=attach(m,B,B,active(m,B),kind);m.playTrainer(A,hand(m,A,"item").instanceId(),null);var q=m.effectCardPrompt(A);m.submitEffectCards(A,q.resolutionId(),q.step(),List.of(card.instanceId()));settle(m);check(m.privateView(B).lostZone().contains(card)&&!m.privateView(B).discard().contains(card)&&!m.privateView(B).hand().contains(card),"Faba Lost Zone was treated as a discard");
    }}
    static void retreat(){var m=game();UUID outgoing=active(m,A);var board=attach(m,A,A,outgoing,"tool");var en=attach(m,A,A,outgoing,"special");var basic=attach(m,A,A,outgoing,"energy");check(m.activeRetreatCost(A)==2,"U-Turn Board did not lower Retreat Cost by one");m.retreat(A,bench(m,A),List.of(en.instanceId(),basic.instanceId()));returned(m,en,true);check(m.privateView(A).discard().contains(basic)&&EventTargetBindingTest.field(m).pokemonView(A,outgoing).attachedTools().contains(board),"Retreat moved nonpaid attachment");}
    static void attackPayment(){String cost="{\"type\":\"discard_tool\",\"target\":\"ALL_OWN_POKEMON\",\"amount\":60,\"minimum\":0,\"bind\":\"tools\"}";String damage="{\"type\":\"damage_per_bound\",\"target\":\"OPPONENT_ACTIVE\",\"bind\":\"tools\",\"amount\":40}";var m=game(DynamicPassiveModifierTest.plainStadium(),trainer("sm2_en_125"),BeforeDamageAttackTest.attack(cost,damage,""));var card=attach(m,A,A,active(m,A),"tool");m.attack(A,"hit");var q=m.effectCardPrompt(A);m.submitEffectCards(A,q.resolutionId(),q.step(),List.of(card.instanceId()));returned(m,card,true);check(m.lastAttack().finalDamage()==160,"Returned Tool did not count as discarded for pre-damage payment");
        var attack=BeforeDamageAttackTest.attack("","","{\"type\":\"discard_energy\",\"target\":\"SELF\",\"amount\":1,\"minimum\":1}");var n=game(DynamicPassiveModifierTest.plainStadium(),trainer("sm2_en_125"),attack);var en=attach(n,A,A,active(n,A),"special");n.attack(A,"hit");q=n.effectCardPrompt(A);n.submitEffectCards(A,q.resolutionId(),q.step(),List.of(en.instanceId()));returned(n,en,true);
    }
    static void knockoutOrder(){var m=DynamicPassiveModifierTest.fixture(trainer("swsh1_en_167"),DynamicPassiveModifierTest.plainStadium(),recycle(),GeneratedRuleBatch8Test.hit(100,false));UUID host=active(m,A);var egg=hand(m,A,"tool");m.playTrainer(A,egg.instanceId(),host);var en=attach(m,A,A,host,"special");m.placeDamageCountersByEffect(A,A,host,20);m.discardHandCardsByEffect(A,A,m.privateView(A).hand().stream().map(CardInstance::instanceId).toList());m.endTurn(A);m.attack(B,"hit");check(m.phase()==MatchPhase.PRIZE_SELECTION&&m.privateView(A).hand().size()==8&&m.privateView(A).hand().contains(en),"Recycle returned before Lucky Egg drew up to seven");settle(m);}
    static void failedAttachment(){var m=game();UUID host=active(m,A);EventTargetBindingTest.field(m).preventHandEnergy(B,A,host);var en=hand(m,A,"special");check(!m.canAttachEnergy(A,en.instanceId(),host),"Locked manual attachment accepted");m.attachEnergyByEffect(A,A,EffectSourceZone.HAND,en.instanceId(),A,host);returned(m,en,false);check(m.activePokemonView(A).attachedEnergyIds().isEmpty(),"Failed attempt briefly attached Energy");}
    static void ai(){for(String id:List.of(TOOLS.getFirst(),ENERGIES.getFirst(),ENERGIES.getLast()))for(var level:AiDifficulty.values()){var m=aiGame(id);UUID p=m.currentPlayer(),host=active(m,p);if(TOOLS.contains(id))m.playTrainer(p,hand(m,p,"trainer").instanceId(),host);else m.attachEnergy(p,hand(m,p,"special").instanceId(),host);var seats=NonPokemonBatch103Test.seats(m);var s=MatchSession.multiplayer(m,seats.get(0),seats.get(1));AiCardOperationTest.settle(s,level);AiCardOperationTest.finish(s,level);check(m.phase()==MatchPhase.FINISHED,"Return card AI stalled");}}
    static void schema(){var effect=new EffectDefinition("discard_from_field_to_hand",EffectTarget.SELF,Map.of(),List.of(),List.of());for(var source:List.of(PassiveModifierProgram.Source.STADIUM,PassiveModifierProgram.Source.ABILITY))GeneratedRuleBatch8Test.reject(()->PassiveModifierProgram.validate(new EffectProgram(List.of(new TriggeredEffects(EffectTrigger.PASSIVE,List.of(),List.of(effect)))),source));GeneratedRuleBatch8Test.reject(()->PassiveRuleProgram.validate(new EffectDefinition(effect.type(),EffectTarget.OPPONENT_ACTIVE,Map.of(),List.of(),List.of())));}
}
